#!/usr/bin/env bash
# make-dmg.sh - Build a distributable DMG for Desgrana.
#
# Usage:
#   make-dmg.sh <app-path> <cli-path> <volume-name> <output-dmg>
#
# Window layout and background come from dmg.DS_Store, generated by
# dmg-layout.sh with the same <volume-name>. No Finder needed here.
# The volume icon is the app icon.

set -euo pipefail

APP_PATH="$1"
CLI_PATH="$2"
VOL_NAME="$3"
OUTPUT_DMG="$4"

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
LAYOUT="$SCRIPT_DIR/dmg.DS_Store"
VOLUME_ICON="$APP_PATH/Contents/Resources/AppIcon.icns"
STAGING=$(mktemp -d)
RW_DMG="${OUTPUT_DMG%.dmg}-rw.dmg"
MOUNTPT=""

cleanup() {
    [ -n "$MOUNTPT" ] && hdiutil detach "$MOUNTPT" -quiet 2>/dev/null || true
    rm -rf "$STAGING" "$RW_DMG" 2>/dev/null || true
}
trap cleanup EXIT

[ -f "$LAYOUT" ] || { echo "✗ $LAYOUT missing: run make dmg-layout." >&2; exit 1; }

#
cp -r "$APP_PATH" "$STAGING/Desgrana.app"
cp    "$CLI_PATH" "$STAGING/desgrana"
ln -s /Applications "$STAGING/Applications"

mkdir -p "$STAGING/.background"
cp "$SCRIPT_DIR/dmg-background.png" "$STAGING/.background/background.png"
cp "$LAYOUT" "$STAGING/.DS_Store"
cp "$VOLUME_ICON" "$STAGING/.VolumeIcon.icns"

#
rm -f "$RW_DMG"
hdiutil create -fs HFS+ \
    -srcfolder "$STAGING" \
    -volname   "$VOL_NAME" \
    -format    UDRW \
    -ov        "$RW_DMG"

# The custom-icon flag lives on the volume root, set it once mounted.
MOUNTPT=$(hdiutil attach "$RW_DMG" -noautoopen -nobrowse \
    | sed -n 's|.*\t\(/Volumes/.*\)|\1|p' \
    | head -1)
xcrun SetFile -a C "$MOUNTPT"

sync
hdiutil detach "$MOUNTPT" -quiet
MOUNTPT=""

#
rm -f "$OUTPUT_DMG"
hdiutil convert "$RW_DMG" -format UDZO -o "$OUTPUT_DMG"

echo "DMG → $OUTPUT_DMG"
